-- SELECT only. Run before dry-run/apply (also the before/after comparison for postcheck). Aggregates and hashes; no row text.
-- 읽기 전용 역할(표 소유자 아님)에서 돈다: information_schema 대신 pg_catalog만 읽는다.
-- 적용 전 기대: 앞 단계 둘(20261024140000, 20261024210000) 적용됨, 줄의 구분은 call·telegram뿐, 트리거 함수가 앞 단계 본문(INVOKER·빈 search_path·private 호출 없음),
--   새 칸·새 함수·새 index·새 CHECK 없음, authenticated는 넣기·지우기·source/title 쓰기 없음, anon·PUBLIC 표 권한 없음.
-- 줄 수와 표 권한·정책 해시는 기록만 하고 사후 확인에서 같은 값이어야 한다(이 migration은 줄·권한·정책을 바꾸지 않는다).
-- expect: feed items rows = 기록
-- expect: feed items personal or unsure rows = 0
-- expect: feed table grants policies hash = 기록
select 'new migration absent' as item,case when not exists(select 1 from supabase_migrations.schema_migrations where version='20261025190000') then '예' else '아니오' end as value
union all select 'previous steps applied (feed table, guard)',case when (select count(*) from supabase_migrations.schema_migrations where version='20261024140000' and name='call_tg_feed')=1 and (select count(*) from supabase_migrations.schema_migrations where version='20261024210000' and name='feed_item_guard_public')=1 and to_regclass('public.app_feed_items') is not null then '예' else '아니오' end
union all select 'rows are call or telegram only',case when not exists(select 1 from public.app_feed_items where source not in('call','telegram')) then '예' else '아니오' end
union all select 'old source and shape checks present, new class check absent',case when (select count(*) from pg_constraint where conrelid=to_regclass('public.app_feed_items') and conname in('app_feed_items_source_check','app_feed_items_shape_check'))=2 and not exists(select 1 from pg_constraint where conrelid=to_regclass('public.app_feed_items') and conname='app_feed_items_call_class_check') then '예' else '아니오' end
union all select 'new columns and index absent',case when not exists(select 1 from pg_attribute where attrelid=to_regclass('public.app_feed_items') and not attisdropped and attname in('moved_at','refilled_at')) and to_regclass('public.app_feed_items_call_ref_key') is null then '예' else '아니오' end
union all select 'new functions absent',case when to_regprocedure('public.app_feed_call_move(uuid,text)') is null and to_regprocedure('public.app_feed_call_work_info(uuid,text,text,uuid)') is null then '예' else '아니오' end
union all select 'guard invoker, empty search_path, no private call (old body)',case when exists(select 1 from pg_proc where oid=to_regprocedure('private.app_feed_item_guard()') and not prosecdef and proconfig=array['search_path=""'] and prosrc not like '%private.%' and prosrc like '%FEED_LINK_SCOPE%' and prosrc not like '%FEED_SOURCE_CALL_ONLY%') then '예' else '아니오' end
union all select 'guard execute revoked from everyone',case when exists(select 1 from pg_proc where oid=to_regprocedure('private.app_feed_item_guard()') and coalesce(proacl::text,'')!~'(^|[{,])(anon|authenticated|service_role)?=') then '예' else '아니오' end
union all select 'one guard trigger',case when (select count(*) from pg_trigger where tgrelid=to_regclass('public.app_feed_items') and not tgisinternal and tgname='app_feed_items_guard')=1 then '예' else '아니오' end
union all select 'owner check function exists (definer)',case when exists(select 1 from pg_proc where oid=to_regprocedure('private.app_is_workspace_owner(uuid)') and prosecdef) then '예' else '아니오' end
union all select 'authenticated cannot insert delete or write source title',case when not has_table_privilege('authenticated','public.app_feed_items','insert') and not has_table_privilege('authenticated','public.app_feed_items','delete') and not has_column_privilege('authenticated','public.app_feed_items','source','update') and not has_column_privilege('authenticated','public.app_feed_items','title','update') then '예' else '아니오' end
union all select 'no anon or PUBLIC table privilege, RLS on, one policy',case when exists(select 1 from pg_class where oid=to_regclass('public.app_feed_items') and relrowsecurity and relacl::text!~'(^|[{,])(anon)?=') and (select count(*) from pg_policy where polrelid=to_regclass('public.app_feed_items'))=1 then '예' else '아니오' end
union all select 'feed items rows',(select count(*)::text from public.app_feed_items)
union all select 'feed items personal or unsure rows',(select count(*)::text from public.app_feed_items where source in('call_personal','call_unsure'))
union all select 'feed table grants policies hash',md5(coalesce((select string_agg(c.relname||':'||c.relrowsecurity::text||':'||coalesce(c.relacl::text,''),',' order by c.relname) from pg_class c where c.oid in(to_regclass('public.app_feed_items'),to_regclass('public.app_feed_days'))),'')
  ||coalesce((select string_agg(a.attname::text||':'||a.attacl::text,',' order by a.attname) from pg_attribute a where a.attrelid=to_regclass('public.app_feed_items') and a.attnum>0 and not a.attisdropped and a.attacl is not null),'')
  ||coalesce((select string_agg(p.polname::text||p.polcmd::text||p.polroles::text||coalesce(pg_get_expr(p.polqual,p.polrelid),'')||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),''),',' order by p.polname) from pg_policy p where p.polrelid in(to_regclass('public.app_feed_items'),to_regclass('public.app_feed_days'))),''));
